if (n == 0) {
        return dcomp(1.0, 0.0);
    }

    // Threshold for Stirling approximation to avoid factorial overflow.
    // 170! is the limit for double precision.
    if (n < 150) {
        dcomp fact = 1.0;
        for (unsigned long i = 1; i <= n; ++i) {
            fact *= static_cast<double>(i);
        }
        return std::pow(alpha, n) / std::sqrt(fact);
    } else {
        // Use Stirling's approximation: ln(n!) approx n*ln(n) - n + 0.5*ln(2*pi*n)
        double ln_alpha_mag = std::log(std::abs(alpha));
        double ln_fact = static_cast<double>(n) * std::log(static_cast<double>(n)) - 
                         static_cast<double>(n) + 
                         0.5 * std::log(2.0 * M_PI * static_cast<double>(n));

        double log_magnitude = static_cast<double>(n) * ln_alpha_mag - 0.5 * ln_fact;
        double magnitude = std::exp(log_magnitude);

        // Phase is n * angle of alpha
        double phase = static_cast<double>(n) * std::arg(alpha);

        return std::polar(magnitude, phase);
    }

